// ConsoleServiceHandler is an implementation of the taramanji.cloud.v1.ConsoleService service.
type ConsoleServiceHandler interface {
	GetOverview(context.Context, *connect.Request[v1.GetOverviewRequest]) (*connect.Response[v1.GetOverviewResponse], error)
	// メトリクスは本番だけ（dev / stg は metrics_enabled = false で、呼ぶと failed_precondition）
	GetMetrics(context.Context, *connect.Request[v1.GetMetricsRequest]) (*connect.Response[v1.GetMetricsResponse], error)
	// あとどのくらいアプリを置けるか（この環境の枠と、Mac mini 全体の空き）。全環境で使える（Datadog は使わない）
	GetCapacity(context.Context, *connect.Request[v1.GetCapacityRequest]) (*connect.Response[v1.GetCapacityResponse], error)
	// 選べるもの（インスタンスタイプ・用意した監視・通知先）と、この環境で使える機能
	GetHostingOptions(context.Context, *connect.Request[v1.GetHostingOptionsRequest]) (*connect.Response[v1.GetHostingOptionsResponse], error)
	// 関数: コンテナイメージを、リクエストが来たときだけ動かす（来なければ 0 台）。外からは API を通してだけ呼べる
	ListFunctions(context.Context, *connect.Request[v1.ListFunctionsRequest]) (*connect.Response[v1.ListFunctionsResponse], error)
	// フォームの定義を YAML にして返す（保存はしない。確かめるだけ）
	PreviewFunction(context.Context, *connect.Request[v1.PreviewFunctionRequest]) (*connect.Response[v1.PreviewFunctionResponse], error)
	// 作る・更新する。フォームの定義（spec）か、YAML そのもの（yaml）のどちらかを渡す
	ApplyFunction(context.Context, *connect.Request[v1.ApplyFunctionRequest]) (*connect.Response[v1.ApplyFunctionResponse], error)
	DeleteFunction(context.Context, *connect.Request[v1.DeleteFunctionRequest]) (*connect.Response[v1.DeleteFunctionResponse], error)
	// API: 公開するホスト名（<名前>-cloud.taramanji.com）と、パスごとの渡し先の関数
	ListApis(context.Context, *connect.Request[v1.ListApisRequest]) (*connect.Response[v1.ListApisResponse], error)
	PreviewApi(context.Context, *connect.Request[v1.PreviewApiRequest]) (*connect.Response[v1.PreviewApiResponse], error)
	ApplyApi(context.Context, *connect.Request[v1.ApplyApiRequest]) (*connect.Response[v1.ApplyApiResponse], error)
	DeleteApi(context.Context, *connect.Request[v1.DeleteApiRequest]) (*connect.Response[v1.DeleteApiResponse], error)
	// API キー: 作るとキーを 1 回だけ返す（YAML にはハッシュだけを残す）
	CreateApiKey(context.Context, *connect.Request[v1.CreateApiKeyRequest]) (*connect.Response[v1.CreateApiKeyResponse], error)
	DeleteApiKey(context.Context, *connect.Request[v1.DeleteApiKeyRequest]) (*connect.Response[v1.DeleteApiKeyResponse], error)
	// バケット: ファイルの置き場（<環境>/buckets/<名前>.yaml の ConfigMap）。外には CDN（ログインあり）か、
	// 公開をオンにしたバケットだけ <バケット>-storage-cloud.taramanji.com（ログインなし）で出せる
	ListBuckets(context.Context, *connect.Request[v1.ListBucketsRequest]) (*connect.Response[v1.ListBucketsResponse], error)
	CreateBucket(context.Context, *connect.Request[v1.CreateBucketRequest]) (*connect.Response[v1.CreateBucketResponse], error)
	// 公開（ログインなしの配信）を切り替える
	UpdateBucket(context.Context, *connect.Request[v1.UpdateBucketRequest]) (*connect.Response[v1.UpdateBucketResponse], error)
	// 空で、どの CDN からも使われていないバケットだけ消せる
	DeleteBucket(context.Context, *connect.Request[v1.DeleteBucketRequest]) (*connect.Response[v1.DeleteBucketResponse], error)
	ListObjects(context.Context, *connect.Request[v1.ListObjectsRequest]) (*connect.Response[v1.ListObjectsResponse], error)
	DeleteObject(context.Context, *connect.Request[v1.DeleteObjectRequest]) (*connect.Response[v1.DeleteObjectResponse], error)
	// Cloudflare のエッジのキャッシュを消す（バケットなら、そのバケットを配っている公開の URL と CDN。CDN なら、その CDN のホスト名）。
	// keys を渡すと、そのファイルの URL だけ消す（アップロードのあと）
	PurgeCache(context.Context, *connect.Request[v1.PurgeCacheRequest]) (*connect.Response[v1.PurgeCacheResponse], error)
	// CDN: 公開するホスト名（<名前>-cloud.taramanji.com）と、その元（バケットか関数）、キャッシュの長さ
	ListDistributions(context.Context, *connect.Request[v1.ListDistributionsRequest]) (*connect.Response[v1.ListDistributionsResponse], error)
	PreviewDistribution(context.Context, *connect.Request[v1.PreviewDistributionRequest]) (*connect.Response[v1.PreviewDistributionResponse], error)
	ApplyDistribution(context.Context, *connect.Request[v1.ApplyDistributionRequest]) (*connect.Response[v1.ApplyDistributionResponse], error)
	DeleteDistribution(context.Context, *connect.Request[v1.DeleteDistributionRequest]) (*connect.Response[v1.DeleteDistributionResponse], error)
	// ---- データベース ----
	// 共有の PostgreSQL / Redis から、データベース（とユーザー）を切り出す（<環境>/databases/<名前>.yaml の ConfigMap）。
	// つなぎ方は、関数の「つなぐデータベース」に足す（接続先が環境変数に入る）。パスワードは画面にも git にも出ない
	ListDatabases(context.Context, *connect.Request[v1.ListDatabasesRequest]) (*connect.Response[v1.ListDatabasesResponse], error)
	CreateDatabase(context.Context, *connect.Request[v1.CreateDatabaseRequest]) (*connect.Response[v1.CreateDatabaseResponse], error)
	// どの関数にもつながれていないデータベースだけ消せる。中身は残る（ログインだけ止める）
	DeleteDatabase(context.Context, *connect.Request[v1.DeleteDatabaseRequest]) (*connect.Response[v1.DeleteDatabaseResponse], error)
	// ---- シークレット ----
	// API キー・パスワードなどの秘密の値（<環境>/secrets/<名前>.yaml の SealedSecret）。値はクラスターの Sealed Secrets の公開鍵で
	// 暗号化してからコミットする（git にも画面にも平文では出ない。読み戻せないので、変えるときは上書きする）。
	// つなぎ方は、関数の「シークレット」に環境変数の名前と一緒に足す（その関数の namespace にだけ置かれる）
	ListSecrets(context.Context, *connect.Request[v1.ListSecretsRequest]) (*connect.Response[v1.ListSecretsResponse], error)
	CreateSecret(context.Context, *connect.Request[v1.CreateSecretRequest]) (*connect.Response[v1.CreateSecretResponse], error)
	// 値を上書きする。つないだ関数は、動いていれば新しい値で入れ替わる
	UpdateSecret(context.Context, *connect.Request[v1.UpdateSecretRequest]) (*connect.Response[v1.UpdateSecretResponse], error)
	// どの関数にもつながれていないシークレットだけ消せる
	DeleteSecret(context.Context, *connect.Request[v1.DeleteSecretRequest]) (*connect.Response[v1.DeleteSecretResponse], error)
	// ---- デプロイの様子 ----
	// コントローラー（デプロイヤー）が、リポジトリの YAML をクラスターに入れた結果と履歴（Argo CD は使わない）
	ListDeployments(context.Context, *connect.Request[v1.ListDeploymentsRequest]) (*connect.Response[v1.ListDeploymentsResponse], error)
	// リポジトリの YAML に合わせて、Datadog のモニターを作り直す（git に直接 push したあとに呼ぶ）
	SyncAlerts(context.Context, *connect.Request[v1.SyncAlertsRequest]) (*connect.Response[v1.SyncAlertsResponse], error)
}

